import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { projectsAPI } from '../../services/api';
import AppLayout from '../../components/layout/AppLayout';

const STATUS_COLORS = { en_cours:'#10B981', termine:'#3B82F6', suspendu:'#EF4444', planifie:'#F59E0B' };
const STATUS_LABELS = { en_cours:'En cours', termine:'Terminé', suspendu:'Suspendu', planifie:'Planifié' };
const TYPE_ICONS = { batiment:'🏗️', route:'🛣️', aep:'💧', assainissement:'🚰', pont:'🌉', autre:'📦' };

export default function ProjectsPage() {
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    projectsAPI.list().then(res => setProjects(res.data)).finally(() => setLoading(false));
  }, []);

  const filtered = filter === 'all' ? projects : projects.filter(p => p.status === filter);

  return (
    <AppLayout>
      <div style={{ padding:'32px 40px' }} className="animate-fade-in">
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-end', marginBottom:32, flexWrap:'wrap', gap:16 }}>
          <div>
            <h1 style={{ fontFamily:'Bebas Neue', fontSize:42, color:'#fff', letterSpacing:1, margin:0 }}>
              Mes <span style={{ color:'#F59E0B' }}>Projets</span>
            </h1>
            <p style={{ color:'#6B7280', margin:'4px 0 0' }}>{projects.length} projet(s) au total</p>
          </div>
          <Link to="/projects/new" className="btn btn-primary">+ Nouveau projet</Link>
        </div>

        {/* Filters */}
        <div style={{ display:'flex', gap:8, marginBottom:24, flexWrap:'wrap' }}>
          {['all', 'en_cours', 'planifie', 'suspendu', 'termine'].map(s => (
            <button key={s} onClick={() => setFilter(s)}
              style={{
                padding:'6px 16px', borderRadius:100, border:'1px solid',
                borderColor: filter === s ? '#F59E0B' : 'rgba(255,255,255,0.1)',
                background: filter === s ? 'rgba(245,158,11,0.1)' : 'transparent',
                color: filter === s ? '#F59E0B' : '#6B7280',
                cursor:'pointer', fontFamily:'Barlow Condensed', fontSize:14, fontWeight:600,
                transition:'all 0.2s',
              }}>
              {s === 'all' ? 'Tous' : STATUS_LABELS[s]}
            </button>
          ))}
        </div>

        {loading ? (
          <div style={{ textAlign:'center', padding:80 }}>
            <div style={{ width:40, height:40, border:'3px solid #F59E0B', borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite', margin:'0 auto 16px' }} />
          </div>
        ) : filtered.length === 0 ? (
          <div className="card" style={{ textAlign:'center', padding:64 }}>
            <div style={{ fontSize:56, marginBottom:16 }}>🏗️</div>
            <h3 style={{ fontFamily:'Bebas Neue', fontSize:28, color:'#fff', marginBottom:8 }}>Aucun projet</h3>
            <p style={{ color:'#6B7280', marginBottom:24 }}>{filter === 'all' ? 'Créez votre premier projet' : 'Aucun projet avec ce statut'}</p>
            {filter === 'all' && <Link to="/projects/new" className="btn btn-primary">Créer un projet</Link>}
          </div>
        ) : (
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(320px, 1fr))', gap:20 }}>
            {filtered.map(project => (
              <Link key={project.id} to={`/projects/${project.id}`} style={{ textDecoration:'none' }}>
                <div className="card" style={{ cursor:'pointer', transition:'all 0.2s', height:'100%' }}
                  onMouseEnter={e => e.currentTarget.style.borderColor = 'rgba(245,158,11,0.3)'}
                  onMouseLeave={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.07)'}>
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:16 }}>
                    <span style={{ fontSize:28 }}>{TYPE_ICONS[project.project_type]}</span>
                    <span style={{ padding:'4px 10px', borderRadius:100, fontSize:12, fontWeight:600,
                      background:`${STATUS_COLORS[project.status]}20`, color:STATUS_COLORS[project.status] }}>
                      {STATUS_LABELS[project.status]}
                    </span>
                  </div>
                  <h3 style={{ fontFamily:'Barlow Condensed', fontSize:20, fontWeight:700, color:'#fff', margin:'0 0 8px', lineHeight:1.2 }}>{project.name}</h3>
                  {project.location && <p style={{ fontSize:13, color:'#6B7280', margin:'0 0 16px' }}>📍 {project.location}</p>}
                  {project.description && <p style={{ fontSize:13, color:'#9CA3AF', margin:'0 0 16px', lineHeight:1.5, display:'-webkit-box', WebkitLineClamp:2, WebkitBoxOrient:'vertical', overflow:'hidden' }}>{project.description}</p>}
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', paddingTop:16, borderTop:'1px solid rgba(255,255,255,0.07)', marginTop:'auto' }}>
                    {project.budget ? (
                      <span style={{ fontSize:13, color:'#F59E0B', fontFamily:'Barlow Condensed', fontWeight:600 }}>
                        {Number(project.budget).toLocaleString('fr-FR')} FCFA
                      </span>
                    ) : <span style={{ fontSize:13, color:'#4B5563' }}>Budget non défini</span>}
                    <span style={{ fontSize:12, color:'#6B7280' }}>{project.contracts_count} contrat(s)</span>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </AppLayout>
  );
}
